MERGE `{{params.project_name}}.semantics_central.FinancingCustomers` final
USING (
{{range_query}}
) staging
ON final.financing_customer_id = staging.financing_customer_id
WHEN MATCHED THEN
UPDATE SET
final.financing_customer_id = staging.financing_customer_id,
final.dealer_id = staging.dealer_id,
final.dealer_manager_id = staging.dealer_manager_id,
final.tax_data = staging.tax_data,
final.address = staging.address,
final.comments = staging.comments,
final.dealership_name = staging.dealership_name ,
final.reference_code = staging.reference_code,
final.documents = staging.documents,
final.created_at = staging.created_at,
final.updated_at = staging.updated_at,
final.deleted_at = staging.deleted_at,
final.created_by_name = staging.created_by_name,
final.created_by_id = staging.created_by_id,
final.updated_by_name = staging.updated_by_name,
final.updated_by_id = staging.updated_by_id,
final.deleted_by_name = staging.deleted_by_name,
final.deleted_by_id = staging.deleted_by_id,
final.risk_score = staging.risk_score,
final.internal_id = staging.internal_id,
final.email = staging.email,
final.phone = staging.phone,
final.country_id = staging.country_id,
final.manual_freeze_reason = staging.manual_freeze_reason,
final.manual_freeze_comments = staging.manual_freeze_comments,
final.is_manual_freeze = staging.is_manual_freeze,
final.first_name = staging.first_name,
final.last_name = staging.last_name,
final.financial_status = staging.financial_status,
final.delivery_blocking = staging.delivery_blocking,
final.bidding_blocking = staging.bidding_blocking,
final.checkout_blocking = staging.checkout_blocking,
final.credit_blocking = staging.credit_blocking
WHEN NOT MATCHED THEN
INSERT (
financing_customer_id,
dealer_id,
dealer_manager_id,
tax_data,
address,
comments,
dealership_name ,
reference_code,
documents,
created_at,
updated_at,
deleted_at,
created_by_name,
created_by_id,
updated_by_name,
updated_by_id,
deleted_by_name,
deleted_by_id,
risk_score,
internal_id,
email,
phone,
country_id,
manual_freeze_reason,
manual_freeze_comments,
is_manual_freeze,
first_name,
last_name,
financial_status,
delivery_blocking,
bidding_blocking,
checkout_blocking,
credit_blocking
) VALUES (
staging.financing_customer_id,
staging.dealer_id,
staging.dealer_manager_id,
staging.tax_data,
staging.address,
staging.comments,
staging.dealership_name ,
staging.reference_code,
staging.documents,
staging.created_at,
staging.updated_at,
staging.deleted_at,
staging.created_by_name,
staging.created_by_id,
staging.updated_by_name,
staging.updated_by_id,
staging.deleted_by_name,
staging.deleted_by_id,
staging.risk_score,
staging.internal_id,
staging.email,
staging.phone,
staging.country_id,
staging.manual_freeze_reason,
staging.manual_freeze_comments,
staging.is_manual_freeze,
staging.first_name,
staging.last_name,
staging.financial_status,
staging.delivery_blocking,
staging.bidding_blocking,
staging.checkout_blocking,
staging.credit_blocking
)